def date_text2num(text):
    """
    Transforms the text into the corresponding number and converts to int.

    @param text: string date to fix.

    @return date: int date fixed.
    """

    if(text == ''):
        text = '-1'
    elif(text == 'today'):
        text = '0'
    elif(text == 'tomorrow'):
        text = '1'

    date = int(text) # Converts to int

    return date

